-- Dedicated development database. No Auth identities inserted. All writes roll back.
begin;
do $test$
declare org uuid:='00000000-0000-0000-0000-000000000001'; v uuid:=gen_random_uuid(); g uuid:=gen_random_uuid(); b uuid; result jsonb; rejected boolean;
begin
 insert into venues(id,organization_id,name,city,maps_url) values(v,org,'Profile rollback court','TEST','https://maps.app.goo.gl/Test');
 insert into games(id,organization_id,venue,city,venue_id,starts_at,ends_at,status,team_price,team_count) values(g,org,'Profile rollback court','TEST',v,now()+interval '2 days',now()+interval '2 days 3 hours','published',120000,2);
 insert into game_positions(game_id,position,capacity,price) select g,p,case when p in ('open','middle') then 4 else 2 end,20000 from unnest(array['open','opposite','middle','setter']) p;
 rejected:=false;
 begin perform dvc_hold(org,null,repeat('a',64),jsonb_build_object('game_id',g,'kind','individual','position','setter','name','No details','contact','test@example.invalid'),gen_random_uuid()); exception when raise_exception then rejected:=true;end;
 assert rejected,'New registrants require balancing details';
 assert not exists(select 1 from bookings where game_id=g),'Missing details leave no partial booking';
 result:=dvc_hold(org,null,repeat('b',64),jsonb_build_object('game_id',g,'kind','team','position','setter','name','Registrant','contact','test@example.invalid','level','intermediate_plus','birth_date','2000-02-29','gender','prefer_not_to_say','teammates','[{"name":"Named teammate","position":"open","level":"developmental_plus","age":25,"gender":"female"}]'::jsonb),gen_random_uuid()); b:=(result->>'id')::uuid;
 assert (select age=extract(year from age((ga.starts_at at time zone 'Asia/Manila')::date,re.birth_date)) and re.birth_date='2000-02-29' and re.level='intermediate_plus' from roster_entries re join bookings bo on bo.id=re.booking_id join games ga on ga.id=bo.game_id where re.booking_id=b and re.is_registrant),'DOB age is calculated for game date';
 assert (select count(*)=1 from roster_entries where booking_id=b and name='Named teammate' and age=25 and birth_date is null and level='developmental_plus' and gender='female'),'Named teammate details persist';
 assert (select count(*)=4 from roster_entries where booking_id=b and name is null and level is null and gender is null and age is null and birth_date is null),'Blank teammates remain unknown';
 assert exists(select 1 from jsonb_array_elements(dvc_bookings(org,null,repeat('b',64))) x where x->>'id'=b::text and x->>'maps_url'='https://maps.app.goo.gl/Test'),'Owned booking has venue link';
 assert jsonb_array_length(dvc_bookings(org,null,repeat('c',64)))=0,'Other guest cannot read profile';
 update bookings set status='reserved' where id=b;
 assert not exists(select 1 from jsonb_array_elements(dvc_roster(org,g)) x where x ?| array['age','birth_date','gender','level']),'Public roster excludes balancing details';
 assert exists(select 1 from jsonb_array_elements(dvc_schedule(org,now(),now()+interval '7 days')) x where x->>'id'=g::text and x->>'maps_url'='https://maps.app.goo.gl/Test'),'Public schedule has venue link';
 update venues set enabled=false,maps_url='https://google.com/maps?q=Updated' where id=v;
 assert exists(select 1 from jsonb_array_elements(dvc_schedule(org,now(),now()+interval '7 days')) x where x->>'id'=g::text and x->>'maps_url'='https://google.com/maps?q=Updated'),'Archived venue retains current link';
 rejected:=false;
 begin update venues set maps_url='https://google.com.evil.test/maps' where id=v; exception when check_violation then rejected:=true;end;
 assert rejected,'Maps host constraint';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"advanced","gender":"male","age":25,"birth_date":"2000-02-29"}',current_date); exception when raise_exception then rejected:=true;end;
 assert rejected,'SQL rejects both age and birthday';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"unknown","gender":"male","age":25}',current_date); exception when raise_exception then rejected:=true;end;
 assert rejected,'SQL rejects unknown level';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"advanced","gender":"unknown","age":25}',current_date); exception when raise_exception then rejected:=true;end;
 assert rejected,'SQL rejects unknown gender';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"advanced","gender":"male","birth_date":"2099-01-01"}',current_date); exception when raise_exception then rejected:=true;end;
 assert rejected,'SQL rejects future birthday';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"advanced","gender":"male","birth_date":"2000-02-30"}',current_date); exception when datetime_field_overflow then rejected:=true;end;
 assert rejected,'SQL rejects impossible birthday';
 rejected:=false;
 begin perform dvc_player_profile('{"level":"advanced","gender":"male","age":121}',current_date); exception when raise_exception then rejected:=true;end;
 assert rejected,'SQL age bounds';
 assert not has_function_privilege('anon','dvc_player_profile(jsonb,date,boolean)','EXECUTE'),'Profile helper is private';
 assert not has_table_privilege('authenticated','roster_entries','SELECT'),'Direct roster profile reads denied';
end $test$;
select 'PASS: profiles, DOB game-date age, optional teammates, atomic denial, public privacy, owner isolation, canonical Maps and SQL validation' as result;
rollback;
